class Solution {
    unordered_map<long long, int> memo;

    int dp(const string& s, int idx, bool tight, bool isLeading, bool hasZero, int sum, int prod) {
        if (idx == (int)s.size()) {
            if (isLeading) return 0;
            return (hasZero || (sum > 0 && prod % sum == 0)) ? 1 : 0;
        }

        long long stateKey = ((long long)idx << 36) |
                             ((long long)tight << 35) |
                             ((long long)isLeading << 34) |
                             ((long long)hasZero << 33) |
                             ((long long)sum << 24) |
                             (long long)prod;

        if (memo.count(stateKey)) return memo[stateKey];

        int limit = tight ? (s[idx] - '0') : 9;
        int total = 0;

        for (int d = 0; d <= limit; ++d) {
            bool nxtTight = tight && (d == limit);
            if (isLeading && d == 0) {
                total += dp(s, idx + 1, nxtTight, true, false, 0, 1);
            } else {
                bool nxtHasZero = hasZero || (d == 0);
                int nxtSum = sum + d;
                int nxtProd = nxtHasZero ? 0 : prod * d;
                total += dp(s, idx + 1, nxtTight, false, nxtHasZero, nxtSum, nxtProd);
            }
        }

        return memo[stateKey] = total;
    }

