import java.util.*;

class Solution {
    private Map<Long, Integer> memo = new HashMap<>();

    private int dp(String s, int idx, boolean tight, boolean isLeading, boolean hasZero, int sum, int prod) {
        if (idx == s.length()) {
            if (isLeading) return 0;
            return (hasZero || (sum > 0 && prod % sum == 0)) ? 1 : 0;
        }

        long key = ((long) idx << 36) |
                   ((long) (tight ? 1 : 0) << 35) |
                   ((long) (isLeading ? 1 : 0) << 34) |
                   ((long) (hasZero ? 1 : 0) << 33) |
                   ((long) sum << 24) |
                   (long) prod;

        if (memo.containsKey(key)) return memo.get(key);

        int limit = tight ? (s.charAt(idx) - '0') : 9;
        int total = 0;

        for (int d = 0; d <= limit; d++) {
            boolean nxtTight = tight && (d == limit);
            if (isLeading && d == 0) {
                total += dp(s, idx + 1, nxtTight, true, false, 0, 1);
            } else {
                boolean nxtHasZero = hasZero || (d == 0);
                int nxtSum = sum + d;
                int nxtProd = nxtHasZero ? 0 : prod * d;
                total += dp(s, idx + 1, nxtTight, false, nxtHasZero, nxtSum, nxtProd);
            }
        }

        memo.put(key, total);
        return total;
    }

    private int count(int val) {
        if (val <= 0) return 0;
        memo.clear();
        return dp(String.valueOf(val), 0, true, true, false, 0, 1);
    }

    public int beautifulNumbers(int l, int r) {
        return count(r) - count(l - 1);
    }
}

